//! Test tolerances (DESIGN.md §9.2), read from `tests/tolerances.toml`.
//!
//! Every correctness test takes its thresholds from that one file, so loosening a gate is a reviewed
//! one-line change. The file is generated by `reference/noise_stats.py --write-tolerances` from measured noise
//! and uses a small TOML subset: `[a.b]` tables, `key = number | "string" | true | false`, and `#` comments.
//! Keys are addressed by their dotted path, e.g. `e2e.bf16.dp_p99`.
//!
//! [`Stats`] is the distribution summary every test prints (p50/p99/max, nearest rank, as the Python side).

use std::collections::BTreeMap;
use std::path::Path;

use anyhow::{Context, Result, bail};

#[derive(Clone, Debug, PartialEq)]
pub enum Value {
    Num(f64),
    Str(String),
    Bool(bool),
}

#[derive(Clone, Debug, Default)]
pub struct Tolerances {
    values: BTreeMap<String, Value>,
}

/// Path of the repository's tolerance file.
pub fn default_path() -> &'static str {
    concat!(env!("CARGO_MANIFEST_DIR"), "/tests/tolerances.toml")
}

impl Tolerances {
    pub fn load(path: impl AsRef<Path>) -> Result<Self> {
        let path = path.as_ref();
        let text = std::fs::read_to_string(path).with_context(|| format!("reading {}", path.display()))?;
        Self::parse(&text).with_context(|| format!("parsing {}", path.display()))
    }

    pub fn load_default() -> Result<Self> {
        Self::load(default_path())
    }

    pub fn parse(text: &str) -> Result<Self> {
        let mut values = BTreeMap::new();
        let mut table = String::new();
        for (n, raw) in text.lines().enumerate() {
            let line = strip_comment(raw).trim();
            if line.is_empty() {
                continue;
            }
            if let Some(rest) = line.strip_prefix('[') {
                let Some(name) = rest.strip_suffix(']') else { bail!("line {}: unterminated table header", n + 1) };
                let name = name.trim();
                if name.is_empty() || !name.split('.').all(is_bare_key) {
                    bail!("line {}: bad table name {name:?}", n + 1);
                }
                table = name.to_string();
                continue;
            }
            let Some((key, val)) = line.split_once('=') else { bail!("line {}: expected key = value", n + 1) };
            let key = key.trim();
            if !is_bare_key(key) {
                bail!("line {}: bad key {key:?}", n + 1);
            }
            let val = parse_value(val.trim()).with_context(|| format!("line {}", n + 1))?;
            let full = if table.is_empty() { key.to_string() } else { format!("{table}.{key}") };
            if values.insert(full.clone(), val).is_some() {
                bail!("line {}: duplicate key {full}", n + 1);
            }
        }
        Ok(Self { values })
    }

    pub fn get(&self, key: &str) -> Option<&Value> {
        self.values.get(key)
    }

    pub fn f64(&self, key: &str) -> Result<f64> {
        match self.values.get(key) {
            Some(Value::Num(x)) => Ok(*x),
            Some(v) => bail!("tolerance {key} is {v:?}, not a number"),
            None => bail!("tolerance {key} is missing from {}", default_path()),
        }
    }

    pub fn str(&self, key: &str) -> Result<&str> {
        match self.values.get(key) {
            Some(Value::Str(s)) => Ok(s),
            Some(v) => bail!("tolerance {key} is {v:?}, not a string"),
            None => bail!("tolerance {key} is missing"),
        }
    }

    /// All keys under `prefix.` (dotted), in order.
    pub fn keys_under<'a>(&'a self, prefix: &'a str) -> impl Iterator<Item = &'a str> + 'a {
        self.values.keys().map(String::as_str).filter(move |k| k.len() > prefix.len() + 1
            && k.starts_with(prefix)
            && k.as_bytes()[prefix.len()] == b'.')
    }

    pub fn keys(&self) -> impl Iterator<Item = &str> {
        self.values.keys().map(String::as_str)
    }
}

fn is_bare_key(k: &str) -> bool {
    !k.is_empty() && k.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}

/// Drop a trailing `# comment`, ignoring `#` inside a double-quoted string.
fn strip_comment(line: &str) -> &str {
    let mut in_str = false;
    for (i, c) in line.char_indices() {
        match c {
            '"' => in_str = !in_str,
            '#' if !in_str => return &line[..i],
            _ => {}
        }
    }
    line
}

fn parse_value(v: &str) -> Result<Value> {
    if let Some(s) = v.strip_prefix('"') {
        let Some(s) = s.strip_suffix('"') else { bail!("unterminated string {v:?}") };
        if s.contains('"') || s.contains('\\') {
            bail!("escapes are not supported in {v:?}");
        }
        return Ok(Value::Str(s.to_string()));
    }
    match v {
        "true" => return Ok(Value::Bool(true)),
        "false" => return Ok(Value::Bool(false)),
        _ => {}
    }
    let x: f64 = v.replace('_', "").parse().with_context(|| format!("bad value {v:?}"))?;
    if !x.is_finite() {
        bail!("non-finite value {v:?}");
    }
    Ok(Value::Num(x))
}

/// Thresholds of the statistical end-to-end gate on the labeled eval set (`[eval.<tier>]`, DESIGN §9.2),
/// derived by `reference/eval/stats.py`. A candidate passes iff, against every reference path of the tier:
/// top-1 disagreement (over all questions, counting only those where the reference's top-1 margin exceeds
/// `disagree_margin`), mean |dp| and p99 |dp| are at most the limits; the lower bound of the
/// paired-bootstrap 95% CI of `acc(candidate) - acc(ref)` is at least `-acc_drop`; and the upper bound of the
/// paired-bootstrap 95% CI of `Brier(candidate) - Brier(ref)` is at most `brier_rise`. `reference/eval/score.py` applies it to a live server.
#[derive(Clone, Debug, PartialEq)]
pub struct EvalGate {
    pub tier: String,
    /// The reference paths whose pairwise envelope the limits come from (`+`-separated in the file).
    pub paths: Vec<String>,
    /// A top-1 change counts as a disagreement only where the reference's top-1 margin exceeds this
    /// (0 = every question; bf16 uses `[e2e.bf16].top1_margin`, DESIGN §9.2's near-tie allowance).
    pub disagree_margin: f64,
    pub disagree: f64,
    pub dp_mean: f64,
    pub dp_p99: f64,
    pub acc_drop: f64,
    pub brier_rise: f64,
}

/// One candidate-vs-reference comparison, as `reference/eval/stats.py compare()` computes it.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct EvalComparison {
    /// Fraction of all questions whose top-1 differs while the reference's top-1 margin exceeds
    /// `EvalGate::disagree_margin`.
    pub disagree: f64,
    pub dp_mean: f64,
    pub dp_p99: f64,
    /// Lower bound of the paired-bootstrap 95% CI of acc(candidate) - acc(reference).
    pub acc_diff_ci_lo: f64,
    /// Upper bound of the paired-bootstrap 95% CI of Brier(candidate) - Brier(reference).
    pub brier_diff_ci_hi: f64,
}

impl EvalGate {
    /// The tiers `tests/tolerances.toml` must carry.
    pub const TIERS: [&'static str; 2] = ["nvfp4", "bf16"];

    pub fn load(t: &Tolerances, tier: &str) -> Result<Self> {
        let k = |name: &str| format!("eval.{tier}.{name}");
        let paths: Vec<String> = t.str(&k("paths"))?.split('+').map(str::to_string).collect();
        if paths.len() < 2 || paths.iter().any(String::is_empty) {
            bail!("eval.{tier}.paths needs at least two reference paths");
        }
        Ok(Self {
            tier: tier.to_string(),
            paths,
            disagree_margin: t.f64(&k("disagree_margin"))?,
            disagree: t.f64(&k("disagree"))?,
            dp_mean: t.f64(&k("dp_mean"))?,
            dp_p99: t.f64(&k("dp_p99"))?,
            acc_drop: t.f64(&k("acc_drop"))?,
            brier_rise: t.f64(&k("brier_rise"))?,
        })
    }

    /// The failed checks of one candidate-vs-reference comparison (empty = this comparison passes).
    pub fn failures(&self, c: &EvalComparison) -> Vec<String> {
        let mut out = Vec::new();
        let mut le = |name: &str, v: f64, lim: f64| {
            if !(v <= lim) {
                out.push(format!("{name} {v:.4e} > {lim:.4e}"));
            }
        };
        le("disagree", c.disagree, self.disagree);
        le("dp_mean", c.dp_mean, self.dp_mean);
        le("dp_p99", c.dp_p99, self.dp_p99);
        le("-acc_ci_lo", -c.acc_diff_ci_lo, self.acc_drop);
        le("brier_ci_hi", c.brier_diff_ci_hi, self.brier_rise);
        out
    }
}

/// Gate (a): per-layer hidden states vs the fp32 truth (`[model.hidden]`, DESIGN §9.2 "Model"), derived and
/// validated by `reference/hidden_dense.py`. Per tap, with `e_c(r)` the candidate's and `e_b(r)` the bf16
/// reference's relative error vs fp32 on the SAME rows `r` (the dense row set, >= `rows_min` rows):
/// (i) `p99(e_c) <= factor x p99(e_b)` (max reported only); (ii) the lower median of `ln(e_c / e_b)` is at most
/// `ln(paired_ratio)`; (iii) with `n_up = #{e_c > sign_ratio e_b}`, `n_down = #{e_b > sign_ratio e_c}`, the
/// one-sided exact binomial `P(X >= k_up | Bin(k_up + k_down, 1/2))` on the counts deflated by the tap's design
/// effect `D` (`k = floor(n / D + 1/2)`; `sign_design_effect`, measured from reference-only bf16 realizations,
/// because rows of one request move together) is at least `sign_alpha`.
#[derive(Clone, Debug, PartialEq)]
pub struct HiddenGate {
    pub factor: f64,
    pub paired_ratio: f64,
    pub sign_ratio: f64,
    pub sign_alpha: f64,
    pub rows_min: usize,
    /// Per tap, in [`HiddenGate::TAPS`] order.
    pub design_effect: [f64; 6],
}

/// One candidate-vs-reference comparison of gate (a) on one tap.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct HiddenComparison {
    pub cand: Stats,
    pub refe: Stats,
    pub median_log_ratio: f64,
    pub n_up: usize,
    pub n_down: usize,
    pub design_effect: f64,
    /// `n_up`, `n_down` deflated by the design effect.
    pub eff_up: usize,
    pub eff_down: usize,
    pub sign_p: f64,
}

impl HiddenGate {
    /// The taps gate (a) covers (`[model.hidden.<tap>]`).
    pub const TAPS: [&'static str; 6] = ["layer0", "layer3", "layer4", "layer15", "layer31", "norm"];
    /// Floor for errors inside the log ratio (an exact zero only occurs for bit-identical rows).
    pub const EPS: f64 = 1e-30;

    pub fn load(t: &Tolerances) -> Result<Self> {
        let rows_min = t.f64("model.hidden.rows_min")?;
        if !(rows_min >= 1.0 && rows_min.fract() == 0.0) {
            bail!("model.hidden.rows_min = {rows_min} is not a positive integer");
        }
        let mut design_effect = [0.0; 6];
        for (d, tap) in design_effect.iter_mut().zip(Self::TAPS) {
            *d = t.f64(&format!("model.hidden.{tap}.sign_design_effect"))?;
            if !(*d >= 1.0) {
                bail!("model.hidden.{tap}.sign_design_effect = {d} is below 1");
            }
        }
        Ok(Self {
            factor: t.f64("factor")?,
            paired_ratio: t.f64("model.hidden.paired_ratio")?,
            sign_ratio: t.f64("model.hidden.sign_ratio")?,
            sign_alpha: t.f64("model.hidden.sign_alpha")?,
            rows_min: rows_min as usize,
            design_effect,
        })
    }

    /// Statistics of candidate errors `cand` against reference errors `refe` (row-aligned, same length) on `tap`.
    pub fn compare(&self, tap: &str, cand: &[f64], refe: &[f64]) -> Result<HiddenComparison> {
        let Some(ti) = Self::TAPS.iter().position(|t| *t == tap) else { bail!("unknown tap {tap}") };
        let d = self.design_effect[ti];
        if cand.len() != refe.len() || cand.is_empty() {
            bail!("gate (a) needs row-aligned, non-empty errors ({} vs {})", cand.len(), refe.len());
        }
        let lr: Vec<f64> = cand.iter().zip(refe).map(|(c, b)| c.max(Self::EPS).ln() - b.max(Self::EPS).ln()).collect();
        let n_up = cand.iter().zip(refe).filter(|(c, b)| **c > self.sign_ratio * **b).count();
        let n_down = cand.iter().zip(refe).filter(|(c, b)| **b > self.sign_ratio * **c).count();
        let eff = |n: usize| (n as f64 / d + 0.5).floor() as usize;
        let (eff_up, eff_down) = (eff(n_up), eff(n_down));
        Ok(HiddenComparison {
            cand: Stats::of(cand).unwrap(),
            refe: Stats::of(refe).unwrap(),
            median_log_ratio: Stats::of(&lr).unwrap().p50,
            n_up,
            n_down,
            design_effect: d,
            eff_up,
            eff_down,
            sign_p: binom_sf_half(eff_up, eff_up + eff_down),
        })
    }

    /// The failed criteria (`p99`, `median_log_ratio`, `sign`; empty = this tap passes).
    pub fn failures(&self, c: &HiddenComparison) -> Vec<String> {
        let mut out = Vec::new();
        if !(c.cand.p99 <= self.factor * c.refe.p99) {
            out.push(format!("p99 {:.4e} > {} x {:.4e}", c.cand.p99, self.factor, c.refe.p99));
        }
        if !(c.median_log_ratio <= self.paired_ratio.ln()) {
            out.push(format!("median_log_ratio {:.4} > ln {}", c.median_log_ratio, self.paired_ratio));
        }
        if !(c.sign_p >= self.sign_alpha) {
            out.push(format!("sign p {:.3e} < {} (rows up {} down {}, design effect {})", c.sign_p, self.sign_alpha,
                             c.n_up, c.n_down, c.design_effect));
        }
        out
    }
}

/// `P(X >= k)` for `X ~ Binomial(n, 1/2)` (log-space sum; relative error ~1e-12).
pub fn binom_sf_half(k: usize, n: usize) -> f64 {
    if k == 0 {
        return 1.0;
    }
    if k > n {
        return 0.0;
    }
    let mut lnf = vec![0.0f64; n + 1];
    for i in 1..=n {
        lnf[i] = lnf[i - 1] + (i as f64).ln();
    }
    let terms: Vec<f64> = (k..=n).map(|i| lnf[n] - lnf[i] - lnf[n - i] - n as f64 * std::f64::consts::LN_2).collect();
    let m = terms.iter().copied().fold(f64::NEG_INFINITY, f64::max);
    (m + terms.iter().map(|t| (t - m).exp()).sum::<f64>().ln()).exp().min(1.0)
}

/// Distribution summary of an error sample (nearest-rank quantiles).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Stats {
    pub n: usize,
    pub p50: f64,
    pub p99: f64,
    pub max: f64,
}

impl Stats {
    pub fn of(xs: &[f64]) -> Option<Stats> {
        if xs.is_empty() {
            return None;
        }
        let mut s = xs.to_vec();
        s.sort_by(f64::total_cmp);
        let q = |p: f64| s[((p * s.len() as f64).ceil() as usize).clamp(1, s.len()) - 1];
        Some(Stats { n: s.len(), p50: q(0.50), p99: q(0.99), max: s[s.len() - 1] })
    }
}

impl std::fmt::Display for Stats {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "n={} p50={:.3e} p99={:.3e} max={:.3e}", self.n, self.p50, self.p99, self.max)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE: &str = r#"
# top comment
schema = 1
note = "a # inside a string"   # trailing
[e2e.bf16]
dp_p99 = 0.015
measured_dp_p99 = 1e-2  # bf16_fork: dp_option p99
strict = true
"#;

    #[test]
    fn parses_the_subset() {
        let t = Tolerances::parse(SAMPLE).unwrap();
        assert_eq!(t.f64("schema").unwrap(), 1.0);
        assert_eq!(t.str("note").unwrap(), "a # inside a string");
        assert_eq!(t.f64("e2e.bf16.dp_p99").unwrap(), 0.015);
        assert_eq!(t.f64("e2e.bf16.measured_dp_p99").unwrap(), 0.01);
        assert_eq!(t.get("e2e.bf16.strict"), Some(&Value::Bool(true)));
        assert_eq!(t.keys_under("e2e.bf16").count(), 3);
        assert!(t.f64("e2e.bf16.missing").is_err());
        assert!(t.f64("note").is_err());
    }

    #[test]
    fn rejects_malformed_input() {
        for bad in ["[e2e", "x", "x = ", "x = \"open", "x = nan", "[a]\nk = 1\nk = 2", "[a b]", "bad key = 1"] {
            assert!(Tolerances::parse(bad).is_err(), "accepted {bad:?}");
        }
    }

    #[test]
    fn stats_use_nearest_rank() {
        let xs: Vec<f64> = (1..=200).map(f64::from).collect();
        let s = Stats::of(&xs).unwrap();
        assert_eq!((s.n, s.p50, s.p99, s.max), (200, 100.0, 198.0, 200.0));
        assert_eq!(Stats::of(&[3.0]).unwrap().p99, 3.0);
        assert!(Stats::of(&[]).is_none());
    }

    /// The committed file parses, and every threshold is exactly what the documented rule derives from its
    /// measurement: `limit = max(factor x measured, floor)` (to the 4 significant digits the generator writes),
    /// where `floor` is an optional `floor_<name>` design value. So no gate sits below the reference noise it
    /// derives from (it could never pass), and no gate is hand-loosened beyond the rule.
    #[test]
    fn repository_tolerances_are_consistent() {
        let t = Tolerances::load_default().unwrap();
        assert_eq!(t.f64("schema").unwrap(), 1.0);
        let factor = t.f64("factor").unwrap();
        assert!(factor >= 1.0);
        let mut checked = 0;
        for key in t.keys() {
            let Some((table, name)) = key.rsplit_once('.') else { continue };
            let Some(base) = name.strip_prefix("measured_") else { continue };
            let threshold = format!("{table}.{base}");
            let Ok(limit) = t.f64(&threshold) else { continue };
            let measured = t.f64(key).unwrap();
            assert!(measured >= 0.0, "{key} = {measured}");
            assert!(limit >= measured, "{threshold} = {limit} is below its measured envelope {measured}");
            let floor = t.f64(&format!("{table}.floor_{base}")).unwrap_or(0.0);
            let rule = (factor * measured).max(floor);
            assert!((limit - rule).abs() <= 1e-3 * rule.max(f64::MIN_POSITIVE),
                    "{threshold} = {limit} is not max(factor x {key}, floor) = {rule}");
            checked += 1;
        }
        assert!(t.f64("e2e.bf16.measured_top1_margin").is_ok(), "top1_margin must carry its measurement");
        for gate in ["e2e.bf16.dp_p99", "e2e.bf16.dp_max", "e2e.fp32_truth.dp_max", "batch_invariance.dp_max",
                     "nvfp4.dp_p99", "nvfp4.dp_max", "e2e.bf16.top1_margin"] {
            assert!(t.f64(gate).is_ok(), "missing {gate}");
        }
        assert!(checked >= 10, "only {checked} thresholds carry a measurement");

        // [eval.<tier>]: the statistical eval-set gates (reference/eval/stats.py). Every limit is covered by the
        // measured_ rule above; here: both tiers load, every gated metric carries its measurement, the NVFP4
        // envelope spans at least three QDQ kernel shapes, and rates stay rates.
        for tier in EvalGate::TIERS {
            let g = EvalGate::load(&t, tier).unwrap_or_else(|e| panic!("[eval.{tier}]: {e:#}"));
            for m in ["disagree", "dp_mean", "dp_p99", "acc_drop", "brier_rise"] {
                assert!(t.f64(&format!("eval.{tier}.measured_{m}")).is_ok(), "eval.{tier}.{m} lacks its measurement");
            }
            for (name, v) in [("disagree", g.disagree), ("acc_drop", g.acc_drop), ("dp_mean", g.dp_mean),
                              ("dp_p99", g.dp_p99), ("brier_rise", g.brier_rise)] {
                assert!(v > 0.0 && v <= 1.0, "eval.{tier}.{name} = {v} is not a rate in (0, 1]");
            }
            assert!(g.dp_mean <= g.dp_p99 || g.dp_p99 == 0.0, "eval.{tier}: mean |dp| above its p99");
            // The generator writes measured_/floor_ at full precision and rounds limits UP, so the rule holds
            // exactly here (no tolerance): a limit never sits below max(factor x measured, floor).
            for m in ["disagree", "dp_mean", "dp_p99", "acc_drop", "brier_rise"] {
                let limit = t.f64(&format!("eval.{tier}.{m}")).unwrap();
                let measured = t.f64(&format!("eval.{tier}.measured_{m}")).unwrap();
                let floor = t.f64(&format!("eval.{tier}.floor_{m}")).unwrap_or(0.0);
                assert!(limit >= (factor * measured).max(floor),
                        "eval.{tier}.{m} = {limit} is below max(factor x {measured}, {floor})");
            }
        }
        // [model.hidden]: gate (a) (reference/hidden_dense.py). The paired and sign ratios are the global factor,
        // the sign test is a real test (alpha in (0, 0.05]), and every tap's p99 limit comes from >= rows_min rows.
        let hg = HiddenGate::load(&t).unwrap_or_else(|e| panic!("[model.hidden]: {e:#}"));
        assert_eq!((hg.paired_ratio, hg.sign_ratio), (factor, factor), "gate (a) ratios must be the global factor");
        assert!(hg.sign_alpha > 0.0 && hg.sign_alpha <= 0.05, "sign_alpha = {}", hg.sign_alpha);
        assert!(hg.rows_min >= 1000, "gate (a) needs >= 1000 rows (A1)");
        for tap in HiddenGate::TAPS {
            let k = |m: &str| format!("model.hidden.{tap}.{m}");
            assert!(t.f64(&k("rel_p99")).is_ok() && t.f64(&k("measured_rel_p99")).is_ok(), "{tap}: no p99 limit");
            let rows = t.f64(&k("measured_rows")).unwrap();
            assert!(rows >= hg.rows_min as f64, "{tap}: measured on {rows} rows < rows_min");
            assert!(t.f64(&k("rel_max")).is_err(), "{tap}: max is reported, not gated (A1)");
            assert!(t.f64(&k("measured_sign_design_effect")).is_ok(), "{tap}: design effect lacks its measurement");
        }
        assert!(EvalGate::load(&t, "nvfp4").unwrap().paths.len() >= 3, "NVFP4 envelope needs >= 3 QDQ paths");
        assert_eq!(EvalGate::load(&t, "nvfp4").unwrap().disagree_margin, 0.0, "NVFP4 counts every top-1 change");
        let bf16 = EvalGate::load(&t, "bf16").unwrap();
        assert_eq!(bf16.disagree_margin, t.f64("e2e.bf16.top1_margin").unwrap(),
                   "eval.bf16.disagree_margin must be the end-to-end near-tie allowance [e2e.bf16].top1_margin");
        assert!(bf16.paths.iter().any(|p| p.starts_with("fp32")),
                "the bf16 envelope must include the fp32 truth path (DESIGN §9.2 binding rule)");
    }

    /// Cross-language check: `reference/eval/stats.py` records, for its validation candidates, the comparison
    /// values against every reference path and which checks failed under the limits it wrote. `EvalGate`
    /// (loaded from the committed file) must reach the same verdict on every one of them.
    #[test]
    fn eval_gate_matches_stats_py() {
        let t = Tolerances::load_default().unwrap();
        let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/golden/dev/eval/report.json");
        let report: serde_json::Value = serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
        let rows = report["rust_fixture"].as_array().expect("report.json lacks rust_fixture; rerun stats.py");
        assert!(rows.len() >= 20, "only {} fixture rows", rows.len());
        let (mut passes, mut fails) = (0, 0);
        for row in rows {
            let tier = row["tier"].as_str().unwrap();
            let g = EvalGate::load(&t, tier).unwrap();
            let lim = |k: &str| row["limits"][k].as_f64().unwrap();
            assert_eq!(
                (g.disagree, g.dp_mean, g.dp_p99, g.acc_drop, g.brier_rise, g.disagree_margin),
                (lim("disagree"), lim("dp_mean"), lim("dp_p99"), lim("acc_drop"), lim("brier_rise"),
                 lim("disagree_margin")),
                "report.json was generated with other [eval.{tier}] limits than the committed ones"
            );
            let v = |k: &str| row["values"][k].as_f64().unwrap();
            let c = EvalComparison {
                disagree: v("disagree"),
                dp_mean: v("dp_mean"),
                dp_p99: v("dp_p99"),
                acc_diff_ci_lo: v("acc_ci_lo"),
                brier_diff_ci_hi: v("brier_ci_hi"),
            };
            let mut got: Vec<String> = g
                .failures(&c)
                .iter()
                .map(|f| f.split_whitespace().next().unwrap().trim_start_matches('-').to_string())
                .collect();
            got.sort();
            let mut want: Vec<String> =
                row["failed"].as_array().unwrap().iter().map(|x| x.as_str().unwrap().to_string()).collect();
            want.sort();
            assert_eq!(got, want, "{} vs {} ({tier})", row["candidate"], row["ref"]);
            if want.is_empty() { passes += 1 } else { fails += 1 }
        }
        assert!(passes > 0 && fails > 0, "the fixture must hold both passing and failing comparisons");
    }

    #[test]
    fn binomial_tail_is_exact_enough() {
        assert_eq!(binom_sf_half(0, 0), 1.0);
        assert_eq!(binom_sf_half(0, 7), 1.0);
        assert_eq!(binom_sf_half(8, 7), 0.0);
        assert!((binom_sf_half(1, 1) - 0.5).abs() < 1e-15);
        // P(X >= 8 | n = 10) = (45 + 10 + 1) / 1024
        assert!((binom_sf_half(8, 10) - 56.0 / 1024.0).abs() < 1e-14);
        assert!((binom_sf_half(5, 10) - 638.0 / 1024.0).abs() < 1e-13);
        // large n: symmetric middle and a deep tail stay finite and ordered
        let (a, b) = (binom_sf_half(2000, 4000), binom_sf_half(2200, 4000));
        assert!(a > 0.5 && a < 0.51 && b > 0.0 && b < 1e-9, "{a} {b}");
    }

    #[test]
    fn hidden_gate_applies_its_rule() {
        let mut text = "factor = 1.5\n[model.hidden]\nrows_min = 4\npaired_ratio = 1.5\nsign_ratio = 1.5\nsign_alpha = 0.01\n"
            .to_string();
        for tap in HiddenGate::TAPS {
            text += &format!("[model.hidden.{tap}]\nsign_design_effect = {}\n", if tap == "norm" { 50.0 } else { 1.0 });
        }
        let g = HiddenGate::load(&Tolerances::parse(&text).unwrap()).unwrap();
        let refe: Vec<f64> = (1..=200).map(|i| 1e-3 * (1.0 + (i % 17) as f64)).collect();
        assert!(g.failures(&g.compare("layer0", &refe, &refe).unwrap()).is_empty(), "the reference passes itself");
        let x2: Vec<f64> = refe.iter().map(|x| 2.0 * x).collect();
        let f = g.failures(&g.compare("layer0", &x2, &refe).unwrap());
        assert_eq!(f.len(), 3, "{f:?}");
        // 10 rows > 1.5x worse, none better: significant on independent rows, not with a design effect of 50
        let mut few = refe.clone();
        few[..10].iter_mut().for_each(|x| *x *= 1.6);
        let c = g.compare("layer0", &few, &refe).unwrap();
        assert_eq!((c.n_up, c.n_down, c.eff_up), (10, 0, 10));
        assert!(g.failures(&c).iter().any(|f| f.starts_with("sign")));
        let c = g.compare("norm", &few, &refe).unwrap();
        assert_eq!((c.eff_up, c.eff_down), (0, 0));
        assert!(g.failures(&c).is_empty(), "design effect 50 deflates 10 rows to none");
        let better: Vec<f64> = refe.iter().map(|x| 0.5 * x).collect();
        assert!(g.failures(&g.compare("layer3", &better, &refe).unwrap()).is_empty());
        let nan: Vec<f64> = refe.iter().map(|_| f64::NAN).collect();
        assert!(!g.failures(&g.compare("layer3", &nan, &refe).unwrap()).is_empty(), "NaN must fail");
        assert!(g.compare("layer3", &refe[..3], &refe).is_err());
        assert!(g.compare("layer5", &refe, &refe).is_err());
    }

    #[test]
    fn eval_gate_applies_its_rule() {
        let t = Tolerances::parse(
            "[eval.bf16]\npaths = \"a+b\"\ndisagree_margin = 0.02\ndisagree = 0.01\ndp_mean = 0.001\ndp_p99 = 0.01\nacc_drop = 0.02\n\
             brier_rise = 0.005\n[eval.nvfp4]\npaths = \"a\"\ndisagree = 0.1\ndp_mean = 0.1\ndp_p99 = 0.1\nacc_drop = 0.1\n",
        )
        .unwrap();
        let g = EvalGate::load(&t, "bf16").unwrap();
        assert_eq!(g.paths, ["a", "b"]);
        assert_eq!(g.disagree_margin, 0.02);
        let ok =
            EvalComparison { disagree: 0.01, dp_mean: 5e-4, dp_p99: 0.009, acc_diff_ci_lo: -0.02, brier_diff_ci_hi: 0.0 };
        assert!(g.failures(&ok).is_empty());
        let bad = EvalComparison { acc_diff_ci_lo: -0.03, brier_diff_ci_hi: 0.01, ..ok };
        assert_eq!(g.failures(&bad).len(), 2);
        let nan = EvalComparison { dp_p99: f64::NAN, ..ok };
        assert_eq!(g.failures(&nan).len(), 1, "NaN must fail");
        assert!(EvalGate::load(&t, "nvfp4").is_err(), "a single reference path is no envelope");
    }
}
